public void validateAndVentilate(Invoice invoice) throws AxelorException {
  validate(invoice);
  if (invoice.getOperationSubTypeSelect() != InvoiceRepository.OPERATION_SUB_TYPE_ADVANCE) {
    ventilate(invoice);
  }
}

/**
 * Validation d'une facture. (Transaction)
 *
 * @param invoice Une facture.
 * @throws AxelorException
 */
@Override
public void validate(Invoice invoice) throws AxelorException {
  if (invoice.getStatusSelect() == null
      || invoice.getStatusSelect() != InvoiceRepository.STATUS_DRAFT) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(AccountExceptionMessage.INVOICE_VALIDATE_WRONG_STATUS));
  }
  validateProcess(invoice);
  if (invoice.getOperationSubTypeSelect() != InvoiceRepository.OPERATION_SUB_TYPE_ADVANCE
      && invoice.getInvoiceAutomaticMailOnValidate()) {
    sendMail(invoice, invoice.getInvoiceMessageTemplateOnValidate());
  }
  invoiceCategoryService.setInvoiceCategory(invoice);
}

@Transactional(rollbackOn = {Exception.class})
protected void validateProcess(Invoice invoice) throws AxelorException {
  log.debug("Invoice validation");

  compute(invoice);

  validateFactory.getValidator(invoice).process();

  // if the invoice is an advance payment invoice, we also "ventilate" it
  // without creating the move
  if (invoice.getOperationSubTypeSelect() == InvoiceRepository.OPERATION_SUB_TYPE_ADVANCE) {
    ventilate(invoice);
  }

public Invoice createRefund(Invoice invoice) throws AxelorException {

  boolean isValidatedAdvancePayment =
      invoice.getStatusSelect() == InvoiceRepository.STATUS_VALIDATED
          && invoice.getOperationSubTypeSelect() == InvoiceRepository.OPERATION_SUB_TYPE_ADVANCE;
  if (invoice.getStatusSelect() != InvoiceRepository.STATUS_VENTILATED
      && !isValidatedAdvancePayment) {
    throw new AxelorException(
        invoice,
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(AccountExceptionMessage.INVOICE_CREATE_REFUND_WRONG_STATUS));
  }

  Invoice refund = new RefundInvoice(invoice).generate();
  invoice.addRefundInvoiceListItem(refund);
  invoiceRepo.save(invoice);

  return refund;

public boolean isNotAwaitingPayment(InvoiceTerm invoiceTerm) {
  if (invoiceTerm == null) {
    return false;
  } else if (invoiceTerm.getInvoice() != null) {
    Invoice invoice = invoiceTerm.getInvoice();

    if (CollectionUtils.isNotEmpty(invoice.getInvoicePaymentList())) {
      return invoice.getInvoicePaymentList().stream()
          .filter(it -> it.getStatusSelect() == InvoicePaymentRepository.STATUS_PENDING)
          .map(InvoicePayment::getInvoiceTermPaymentList)
          .flatMap(Collection::stream)
          .map(InvoiceTermPayment::getInvoiceTerm)
          .noneMatch(it -> it.getId().equals(invoiceTerm.getId()));
    }
  }

  return true;
}

protected boolean isBlocking(InvoiceTerm invoiceTerm, PaymentSession paymentSession) {
  if (paymentSession.getPaymentMode().getTypeSelect() != PaymentModeRepository.TYPE_DD) {
    return false;
  }

  if (invoiceTerm.getInvoice() != null) {
    Invoice invoice = invoiceTerm.getInvoice();

    if (invoice.getDebitBlockingOk()
        && !paymentSession.getPaymentDate().isAfter(invoice.getDebitBlockingToDate())) {
      return true;
    }

    if (this.isBlocking(invoice.getPartner(), paymentSession)) {
      return true;
    }

    if (this.isLcrBlocking(invoice, invoiceTerm.getDueDate())
        && paymentSession.getPaymentMode().getTypeSelect()
            != PaymentModeRepository.TYPE_EXCHANGES) {
      return true;
    }
  }

  if (invoiceTerm.getMoveLine() != null) {
    MoveLine moveLine = invoiceTerm.getMoveLine();

    if (moveLine.getPartner() != null && this.isBlocking(moveLine.getPartner(), paymentSession)) {
      return true;
    } else if (moveLine.getMove().getPartner() != null
        && this.isBlocking(moveLine.getMove().getPartner(), paymentSession)) {
      return true;
    }
  }

  return false;
